(def probe-source
  "Exact historical MCP forms. Load the recorded base probe and classloader first;
   evaluate this source in user in the isolated development JVM, never default."
  "; Historical MCP JVM probe. Acquire the isolated operator root and test classloader\n; as recorded in the landing note before loading. No test JVM is started.\n(defn reds19-seed-probe [label]\n  (let [writes (atom [])\n        transact seon.db/transact!]\n    (try\n      (with-redefs [seon.db/transact!\n                    (fn [connection transaction]\n                      (let [result (transact connection transaction)]\n                        (swap! writes conj\n                               {:transaction transaction\n                                :result (if (:seon.error/kind result)\n                                          result\n                                          (-> result\n                                              (dissoc :db-before :db-after)\n                                              (assoc :committed? (some? (:db-after result)))))})\n                        (when (:seon.error/kind result)\n                          (throw (ex-info \"Seed refused; body skipped\" result)))\n                        result))]\n        (#'seon.cluster.turn-test/with-cluster\n         (fn [cluster]\n           {:agent (seon.db/pull\n                    (seon.db/db (:seon.db/connection cluster))\n                    '[*] [:seon.agent/id \"agent-a\"])})))\n      (catch Exception failure\n        {:failure (ex-data failure)})\n      (finally\n        (spit (str \"/Users/sean/src/seon/tmp/turn-test-reds19/seed-\" label \".edn\")\n              (pr-str @writes))))\n    {:label label :write-count (count @writes)\n     :refusals (into [] (keep #(when (:seon.error/kind (:result %)) %)) @writes)}))\n\n(defn reds19-seeds [labels]\n  (let [connection (seon.operator/connection \"turn-test-reds19\")\n        database (seon.db/db connection)]\n    (seon.schema/call-with-projection\n     (seon.db/carried-projection database)\n     (fn []\n       (let [manifest (seon.fn/build-manifest\n                       {:seon.fn/roots [\"/Users/sean/src/seon/tmp/turn-test-reds19-wt/src\" \"/Users/sean/src/seon/tmp/turn-test-reds19-wt/test\"]})\n             base (with-redefs-fn\n                    {#'seon.test-support/source-manifest (delay manifest)}\n                    #(#'seon.test-support/create-base nil))]\n         (try\n           (with-redefs-fn\n             {(ns-resolve 'seon.test-support 'database-base) (delay base)}\n             #(mapv reds19-seed-probe labels))\n           (finally (#'seon.test-support/close-base! base))))))))\n\n(require 'seon.test-support 'seon.cluster.turn-test 'seon.operator\n         'seon.db 'seon.schema 'seon.fn 'seon.test 'seon.test.runner\n         'seon.config)\n\n(defn reds19-checked-run\n  \"Run named tests serially on fresh canonical branches and SCI contexts.\"\n  [label test-names]\n  (let [connection (seon.operator/connection \"turn-test-reds19\")\n        database (seon.db/db connection)]\n    (seon.schema/call-with-projection\n     (seon.db/carried-projection database)\n     (fn []\n       (let [manifest (seon.fn/build-manifest\n                       {:seon.fn/roots [\"/Users/sean/src/seon/tmp/turn-test-reds19-wt/src\" \"/Users/sean/src/seon/tmp/turn-test-reds19-wt/test\"]})\n             base (with-redefs-fn\n                    {#'seon.test-support/source-manifest (delay manifest)}\n                    #(#'seon.test-support/create-base nil))]\n         (try\n           (with-redefs-fn\n             {(ns-resolve 'seon.test-support 'database-base) (delay base)}\n             (fn []\n               (mapv\n                (fn [test-name]\n                  (let [refusals (atom [])\n                        transact seon.db/transact!\n                        result\n                        (with-redefs [seon.db/transact!\n                                      (fn [target transaction]\n                                        (let [result (transact target transaction)]\n                                          (when (:seon.error/kind result)\n                                            (swap! refusals conj\n                                                   {:transaction transaction\n                                                    :result result\n                                                    :stack (mapv str (.getStackTrace (Exception.)))})\n                                            (throw (ex-info \"Refused write; subsequent assertions skipped\" result)))\n                                          result))]\n                        (seon.test/run\n                         (requiring-resolve (symbol test-name))\n                         connection\n                         {:seon.test.run/provenance\n                          (seon.test.runner/provenance (seon.db/db connection))\n                          :seon.test/remaining-ms\n                          (:seon.test/check-time-limit-ms\n                           (seon.config/effective (seon.db/db connection) \"turn-test-reds19\"))}))]\n                    (spit (str \"/Users/sean/src/seon/tmp/turn-test-reds19/refusals-\" (clojure.string/replace test-name \"/\" \"--\") \".edn\") (pr-str @refusals))\n                    (spit (str \"/Users/sean/src/seon/tmp/turn-test-reds19/\" label \"-\" (clojure.string/replace test-name \"/\" \"--\") \".edn\")\n                          (pr-str result))\n                    (select-keys result [:seon.test/sym :seon.test/pass-count\n                                         :seon.test/fail-count :seon.test/error-count\n                                         :seon.test/run])))\n                test-names)))\n           (finally (#'seon.test-support/close-base! base))))))))\n\n\n(def reds19-future\n (future\n  (let [thread (Thread/currentThread) entering (.getContextClassLoader thread)]\n   (try\n    (.setContextClassLoader thread reds19-loader)\n    (with-bindings {clojure.lang.Compiler/LOADER reds19-loader}\n      (require 'seon.cluster.turn-test :reload)\n      (load-file \"/Users/sean/src/seon/tmp/turn-test-reds19/checked-probe.clj\")\n      ((resolve 'user/reds19-checked-run) \"checked\" [\"seon.cluster.turn-test/refused-terminal-program-transactions-settle-and-do-not-refire\" \"seon.cluster.turn-test/delimiter-repair-is-span-local-and-precedes-intent\" \"seon.cluster.turn-test/a-run-prompts-from-its-opening-database-value\" \"seon.cluster.turn-test/runtime-schema-key-changes-pass-the-one-usage-guarded-decision\" \"seon.cluster.turn-test/turn-intent-is-the-complete-crash-falsifier\" \"seon.cluster.turn-test/a-prompt-refusal-is-a-recorded-error-value-never-a-throw\" \"seon.cluster.turn-test/generated-fixed-point-closes-the-run\" \"seon.cluster.turn-test/generated-membership-failure-never-advances-the-run-to-call\" \"seon.cluster.turn-test/generated-phase-failures-converge-through-one-terminal-exit\" \"seon.cluster.turn-test/streaming-writes-zero-datoms-test\" \"seon.cluster.turn-test/a-lost-model-call-leaves-a-durable-readable-reason\" \"seon.cluster.turn-test/a-refused-definition-stays-in-its-agents-defs\" \"seon.cluster.turn-test/concurrent-streams-share-one-conn-test\" \"seon.cluster.turn-test/generated-model-attempt-traces-preserve-presence-and-episode-laws\" \"seon.cluster.turn-test/runtime-schema-unregister-removes-one-unused-global-schema\"]))\n    (finally (.setContextClassLoader thread entering))))))\n")

(comment
  (binding [*ns* (find-ns 'user)]
